    cartan_labels = [f"H_{k}" for k in range(1, n + 2)]
    for lbl, cv in zip(cartan_labels, _solve_cartan(b, n)):
        if cv:
            result[lbl] = result.get(lbl, Fraction(0)) + cv

    return _clean(result)


# ── Schema 1 JSON builder ─────────────────────────────────────────────────────

def dim_even(n: int) -> int:
