#!/usr/bin/env python3
"""
src/C_gamma.py

Compute Schema 2 (gamma / inhomogeneous deformation) for C(n+1) = osp(2|2n).
Outputs C_{n}_gamma.json for n = 1, 2, 3.

Sign convention (Option A, from C_inhomogeneous_definition.md):
    [b_j^s, a_1^sigma]_gamma = -gb_{sigma,j,s} * kappa

The 2-cocycle γ(X_a, X_b) is the coefficient of kappa in [X_a, X_b]_gamma,
expressed as a linear combination of generators with coefficients linear in gb.
"""

import json
import os
from fractions import Fraction
from datetime import date

# Import the core oscillator algebra from C_generators
import sys
sys.path.insert(0, os.path.dirname(__file__))
from C_generators import (
    build_generators, express, dim_even, dim_odd, dim_total,
    _is_fermionic, _sort_mono, _frac_str,
)


# ── gb parameter labels ───────────────────────────────────────────────────────

def _gb_label(fermion_idx: int, boson_idx: int) -> str:
    """
    Return the gb label for the deformation [b_j^s, a_1^sigma] = -gb * kappa.
    fermion_idx: 0 = a_1_p (sigma=+), 1 = a_1_m (sigma=-)
    boson_idx:   2k = b_k_p (s=+),   2k+1 = b_k_m (s=-)
    """
    sigma = "p" if fermion_idx == 0 else "m"
    k = boson_idx // 2
    s = "p" if boson_idx % 2 == 0 else "m"
    return f"gb_a1{sigma}_b{k}{s}"


def _gb_matrix_labels(n: int) -> list:
    """
    Return 2×2n gb label matrix as a list of two rows.
    Rows: [a_1_p, a_1_m];  Cols: [b_1_p, b_1_m, ..., b_n_p, b_n_m].
    """
    rows = []
    for fi in [0, 1]:
        row = [_gb_label(fi, 2 * k + s) for k in range(1, n + 1) for s in [0, 1]]
        rows.append(row)
    return rows


# ── Deformed normal-ordering ──────────────────────────────────────────────────
# Returns (regular_poly, kappa_parts) where:
#   regular_poly = {tuple: Fraction}          (undeformed part)
#   kappa_parts  = {gb_label: {tuple: Fraction}}  (first-order deformation)
#
# Second-order (and higher) gb terms are discarded because kappa^2 = 0.

def _sort_mono_def(mono: tuple):
    """Deformed normal-ordering of a monomial. See module docstring."""
    indices = list(mono)
    for i in range(len(indices) - 1):
        if indices[i] > indices[i + 1]:
            a, b = indices[i], indices[i + 1]
            pa = 1 if _is_fermionic(a) else 0
            pb = 1 if _is_fermionic(b) else 0
            swap_sign = Fraction((-1) ** (pa * pb))

            prefix = indices[:i]
            suffix = indices[i + 2:]

            # Standard (anti)commutator extra value
            std_extra = Fraction(0)
            if pa and pb:
                std_extra = Fraction(1)                      # {a_1_m, a_1_p} = 1
            elif (not pa) and (not pb):
                if a % 2 == 1 and b % 2 == 0 and a == b + 1:
                    std_extra = Fraction(1)                  # [b_k_m, b_k_p] = 1

            # Deformation extra: only for mixed (boson a, fermion b)
            # [b_j^s, a_1^sigma] = -gb * kappa  → extra = -gb
            gb_lbl = None
            if (not pa) and pb:
                gb_lbl = _gb_label(b, a)                     # b = fermion idx, a = boson idx

            # ── Recurse on the swapped main term ──
            m_reg, m_kap = _sort_mono_def(tuple(prefix + [b, a] + suffix))
            res_reg = {k: swap_sign * v for k, v in m_reg.items()}
            res_kap = {g: {k: swap_sign * v for k, v in p.items()}
                       for g, p in m_kap.items()}

            # ── Standard extra term (anticommutator / commutator = 1) ──
            if std_extra:
                e_reg, e_kap = _sort_mono_def(tuple(prefix + suffix))
                for k, v in e_reg.items():
                    res_reg[k] = res_reg.get(k, Fraction(0)) + std_extra * v
                for g, p in e_kap.items():
                    res_kap.setdefault(g, {})
                    for k, v in p.items():
                        res_kap[g][k] = res_kap[g].get(k, Fraction(0)) + std_extra * v

            # ── Deformation extra: contributes to kappa part only ──
            # [b_j^s, a_1^sigma]_gamma = -gb * kappa, so the "context" (prefix+suffix)
            # contributes -1 * sort_regular(prefix + suffix) to kappa_parts[gb_lbl].
            # (Second-order gb terms from further commutations in the context are
            #  discarded since kappa^2 = 0.)
            if gb_lbl is not None:
                ctx_reg = _sort_mono(tuple(prefix + suffix))  # undeformed sort only
                res_kap.setdefault(gb_lbl, {})
                for k, v in ctx_reg.items():
                    res_kap[gb_lbl][k] = res_kap[gb_lbl].get(k, Fraction(0)) + Fraction(-1) * v

            # Clean zeros
            res_reg = {k: v for k, v in res_reg.items() if v}
            res_kap = {g: {k: v for k, v in p.items() if v}
                       for g, p in res_kap.items()}
            res_kap = {g: p for g, p in res_kap.items() if p}
            return res_reg, res_kap

    # Already in PBW order; check fermionic self-product
    for i in range(len(indices) - 1):
        if indices[i] == indices[i + 1] and _is_fermionic(indices[i]):
            return {}, {}
    return {mono: Fraction(1)}, {}


# ── Deformed polynomial multiplication ───────────────────────────────────────

def _mul_def(p1_reg, p1_kap, p2_reg, p2_kap):
    """
    Multiply two deformed polynomials (reg, kap).
    kap × kap terms are O(kappa^2) and are discarded.
    """
    res_reg = {}
    res_kap = {}

    for m1, c1 in p1_reg.items():
        for m2, c2 in p2_reg.items():
            # regular × regular → regular
            sub_reg, sub_kap = _sort_mono_def(m1 + m2)
            for k, v in sub_reg.items():
                res_reg[k] = res_reg.get(k, Fraction(0)) + c1 * c2 * v
            # regular × kap from monomial product → kap
            for g, p in sub_kap.items():
                res_kap.setdefault(g, {})
                for k, v in p.items():
                    res_kap[g][k] = res_kap[g].get(k, Fraction(0)) + c1 * c2 * v

    # p1_reg × p2_kap
    for m1, c1 in p1_reg.items():
        for g2, p2 in p2_kap.items():
            for m2, c2 in p2.items():
                for k, v in _sort_mono(m1 + m2).items():
                    res_kap.setdefault(g2, {})
                    res_kap[g2][k] = res_kap[g2].get(k, Fraction(0)) + c1 * c2 * v

    # p1_kap × p2_reg
    for g1, p1 in p1_kap.items():
        for m1, c1 in p1.items():
            for m2, c2 in p2_reg.items():
                for k, v in _sort_mono(m1 + m2).items():
                    res_kap.setdefault(g1, {})
                    res_kap[g1][k] = res_kap[g1].get(k, Fraction(0)) + c1 * c2 * v

    res_reg = {k: v for k, v in res_reg.items() if v}
    res_kap = {g: {k: v for k, v in p.items() if v}
               for g, p in res_kap.items()}
    res_kap = {g: p for g, p in res_kap.items() if p}
    return res_reg, res_kap


def bracket_def(X_reg, X_kap, px, Y_reg, Y_kap, py):
    """Graded bracket [X, Y}_gamma = XY - (-1)^{px*py} YX, first order in gb."""
    sign = Fraction((-1) ** (px * py))
    xy_reg, xy_kap = _mul_def(X_reg, X_kap, Y_reg, Y_kap)
    yx_reg, yx_kap = _mul_def(Y_reg, Y_kap, X_reg, X_kap)

    res_reg = {}
    for k, v in xy_reg.items():
        res_reg[k] = res_reg.get(k, Fraction(0)) + v
    for k, v in yx_reg.items():
        res_reg[k] = res_reg.get(k, Fraction(0)) - sign * v

    res_kap = {}
    for g, p in xy_kap.items():
        res_kap.setdefault(g, {})
        for k, v in p.items():
            res_kap[g][k] = res_kap[g].get(k, Fraction(0)) + v
    for g, p in yx_kap.items():
        res_kap.setdefault(g, {})
        for k, v in p.items():
            res_kap[g][k] = res_kap[g].get(k, Fraction(0)) - sign * v

    res_reg = {k: v for k, v in res_reg.items() if v}
    res_kap = {g: {k: v for k, v in p.items() if v}
               for g, p in res_kap.items()}
    res_kap = {g: p for g, p in res_kap.items() if p}
    return res_reg, res_kap


# ── Gamma computation ─────────────────────────────────────────────────────────

def compute_gamma(n: int):
    """
    Compute all non-zero gamma entries for C(n+1) = osp(2|2n).
    Returns list of dicts:
      {"X": lbl, "Y": lbl, "Z": lbl, "gb_terms": [{"gb": gb_lbl, "scalar": str}]}
    """
    gens, par, basis = build_generators(n)

    # Represent each generator as (reg, kap={}) — no gb in the generators themselves
    gen_def = {lbl: (gp, {}) for lbl, gp in gens.items()}

    entries = []
    for i, xi in enumerate(basis):
        for j, xj in enumerate(basis):
            if j < i:
                continue
            xi_reg, xi_kap = gen_def[xi]
            xj_reg, xj_kap = gen_def[xj]
            _, kap = bracket_def(xi_reg, xi_kap, par[xi],
                                 xj_reg, xj_kap, par[xj])
            if not kap:
                continue

            # Express each gb component in the Lie algebra basis
            for gb_lbl, poly in sorted(kap.items()):
                coeffs = express(poly, n, gens)
                if not coeffs:
                    continue
                for z, c in sorted(coeffs.items()):
                    # Forward pair (xi, xj)
                    entries.append({
                        "X": xi, "Y": xj, "Z": z,
                        "gb_terms": [{"gb": gb_lbl, "scalar": _frac_str(c)}],
                    })
                    # Reverse pair (xj, xi): gamma is antisymmetric like the bracket
                    # [Y, X}_gamma = -(-1)^{px*py} [X, Y}_gamma
                    # => gamma(Y, X; Z) = -(-1)^{px*py} * gamma(X, Y; Z)
                    if i != j:
                        sign = (-1) ** (par[xi] * par[xj])
                        rev_c = -sign * c
                        if rev_c:
                            entries.append({
                                "X": xj, "Y": xi, "Z": z,
                                "gb_terms": [{"gb": gb_lbl, "scalar": _frac_str(rev_c)}],
                            })

    # Merge entries with same (X, Y, Z): combine gb_terms lists
    merged = {}
    for e in entries:
        key = (e["X"], e["Y"], e["Z"])
        if key not in merged:
            merged[key] = {"X": e["X"], "Y": e["Y"], "Z": e["Z"], "gb_terms": []}
        merged[key]["gb_terms"].extend(e["gb_terms"])

    return list(merged.values())


# ── Schema 2 builder ──────────────────────────────────────────────────────────

def build_gamma_schema(n: int) -> dict:
    gens, par, basis = build_generators(n)
    boson_cols = [f"b_{k}_{'p' if s==0 else 'm'}" for k in range(1, n+1) for s in [0,1]]
    gb_matrix_rows = _gb_matrix_labels(n)
    gamma_entries = compute_gamma(n)

    return {
        "schema_version": "5.0",
        "algebra": {
            "family": "C",
            "m": 1,
            "n": n,
            "cartan_type": f"C({n+1})",
            "alternative_notation": {
                "osp": f"osp(2|{2*n})",
                "dimension_formula": "osp(2m|2n) with m=1",
            },
            "dimension": {
                "total": dim_total(n),
                "even": dim_even(n),
                "odd": dim_odd(n),
            },
        },
        "schema1_ref": f"C_{n}_structure.json",
        "inhomogeneous_deformation": {
            "deformation_relation": "[b_j^s, a_1^sigma]_gamma = -gb_{sigma,j,s} * kappa",
            "sign_convention": "Option A: negative sign as in C_inhomogeneous_definition.md",
            "kappa_parity": 1,
            "gb_count": 4 * n,
            "gb_matrix": {
                "shape": [2, 2 * n],
                "rows": ["a_1_p", "a_1_m"],
                "cols": boson_cols,
                "labels": gb_matrix_rows,
            },
            "gamma_entries": gamma_entries,
        },
        "metadata": {
            "generated_by": "src/C_gamma.py",
            "generation_date": date.today().isoformat(),
            "n": n,
            "gamma_entry_count": len(gamma_entries),
            "references": [
                "Frappat, Sciarrino, Sorba, Dictionary on Lie Algebras and Superalgebras (2000)",
                "arXiv:hep-th/9607161",
            ],
        },
    }


def main():
    data_dir = os.path.join(os.path.dirname(__file__), "..", "data")
    os.makedirs(data_dir, exist_ok=True)
    for n in [1, 2, 3]:
        print(f"Computing gamma for C({n+1}) = osp(2|{2*n}), n={n}...")
        schema = build_gamma_schema(n)
        out = os.path.join(data_dir, f"C_{n}_gamma.json")
        with open(out, "w") as f:
            json.dump(schema, f, indent=2)
        count = schema["metadata"]["gamma_entry_count"]
        print(f"  gamma entries: {count}")
        print(f"  gb parameters: {schema['inhomogeneous_deformation']['gb_count']}")
        print(f"  written: {out}")


if __name__ == "__main__":
    main()

"""
tests/test_C_generators.py

Unit tests for C(n+1) = osp(2|2n) structure constant generator.
"""

import sys
import os
import json
import pytest
from fractions import Fraction

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from C_generators import (
    build_generators,
    bracket,
    express,
    build_schema,
    dim_even,
    dim_odd,
    dim_total,
)


# ── 1. Dimension checks ───────────────────────────────────────────────────────

@pytest.mark.parametrize("n,ev,od,tot", [
    (1,  4,  4,  8),
    (2, 11,  8, 19),
    (3, 22, 12, 34),
])
def test_dimension_formulas(n, ev, od, tot):
    assert dim_even(n) == ev
    assert dim_odd(n) == od
    assert dim_total(n) == tot


@pytest.mark.parametrize("n", [1, 2, 3])
def test_basis_count_matches_dimension(n):
    gens, par, basis = build_generators(n)
    even_count = sum(1 for l in basis if par[l] == 0)
    odd_count  = sum(1 for l in basis if par[l] == 1)
    assert even_count == dim_even(n), f"n={n}: even count {even_count} != {dim_even(n)}"
    assert odd_count  == dim_odd(n),  f"n={n}: odd count {odd_count} != {dim_odd(n)}"


# ── 2. Parity checks ──────────────────────────────────────────────────────────

@pytest.mark.parametrize("n", [1, 2, 3])
def test_parity_assignment(n):
    gens, par, basis = build_generators(n)
    for lbl in basis:
        if "eps1" in lbl:
            assert par[lbl] == 1, f"{lbl} should be odd (parity 1)"
        elif lbl.startswith("H_") or lbl.startswith("E_2del") or lbl.startswith("E_del"):
            assert par[lbl] == 0, f"{lbl} should be even (parity 0)"


# ── 3. Specific structure constants ──────────────────────────────────────────

@pytest.mark.parametrize("n", [1, 2, 3])
def test_cartan_brackets_zero(n):
    """[H_i, H_j] = 0 for all i, j."""
    gens, par, basis = build_generators(n)
    cartans = [l for l in basis if l.startswith("H_")]
    for i, hi in enumerate(cartans):
        for j, hj in enumerate(cartans):
            if j < i:
                continue
            br = bracket(gens[hi], gens[hj], 0, 0)
            result = express(br, n, gens)
            assert not result, f"n={n}: [{hi},{hj}] = {result}, expected 0"


@pytest.mark.parametrize("n", [1, 2, 3])
def test_H1_eps_pp_eigenvalue(n):
    """[H_1, E_eps1_del1_pp] = 2 * E_eps1_del1_pp."""
    gens, par, _ = build_generators(n)
    br = bracket(gens["H_1"], gens["E_eps1_del1_pp"], 0, 1)
    result = express(br, n, gens)
    assert result == {"E_eps1_del1_pp": Fraction(2)}, f"n={n}: got {result}"


@pytest.mark.parametrize("n", [1, 2, 3])
def test_H1_eps_pm_zero(n):
    """[H_1, E_eps1_del1_pm] = 0  (ε−δ_1 is isotropic w.r.t. H_1)."""
    gens, par, _ = build_generators(n)
    br = bracket(gens["H_1"], gens["E_eps1_del1_pm"], 0, 1)
    result = express(br, n, gens)
    assert not result, f"n={n}: [{{'H_1','E_eps1_del1_pm'}}] = {result}, expected 0"


@pytest.mark.parametrize("n", [1, 2, 3])
def test_Hn1_E2deln_p_eigenvalue(n):
    """[H_{n+1}, E_2del{n}_p] = -2 * E_2del{n}_p."""
    gens, par, _ = build_generators(n)
    lbl_H = f"H_{n + 1}"
    lbl_E = f"E_2del{n}_p"
    br = bracket(gens[lbl_H], gens[lbl_E], 0, 0)
    result = express(br, n, gens)
    assert result == {lbl_E: Fraction(-2)}, f"n={n}: got {result}"


def test_eps_pp_mm_bracket_n1():
    """[E_eps1_del1_pp, E_eps1_del1_mm] = -H_1 - 2*H_2  for n=1."""
    n = 1
    gens, par, _ = build_generators(n)
    br = bracket(gens["E_eps1_del1_pp"], gens["E_eps1_del1_mm"], 1, 1)
    result = express(br, n, gens)
    expected = {"H_1": Fraction(-1), "H_2": Fraction(-2)}
    assert result == expected, f"Got {result}"


@pytest.mark.parametrize("n", [1, 2, 3])
def test_E2del1p_E2del1m_bracket(n):
    """[E_2del1_p, E_2del1_m] should be a Cartan element (non-zero)."""
    gens, par, _ = build_generators(n)
    br = bracket(gens["E_2del1_p"], gens["E_2del1_m"], 0, 0)
    result = express(br, n, gens)
    assert result, f"n={n}: [E_2del1_p, E_2del1_m] is unexpectedly 0"
    # All non-zero contributions should be Cartan
    for lbl in result:
        assert lbl.startswith("H_"), f"n={n}: unexpected non-Cartan term {lbl}"


# ── 4. Graded antisymmetry ────────────────────────────────────────────────────

@pytest.mark.parametrize("n", [1, 2, 3])
def test_graded_antisymmetry(n):
    """[X, Y} = -(-1)^{px*py} [Y, X}."""
    gens, par, basis = build_generators(n)
    test_pairs = [
        ("H_1", "E_eps1_del1_pp"),
        ("E_eps1_del1_pp", "E_eps1_del1_mm"),
        ("H_1", "E_2del1_p"),
        ("E_eps1_del1_pp", "E_eps1_del1_pm"),
    ]
    for lx, ly in test_pairs:
        px, py = par[lx], par[ly]
        r_xy = express(bracket(gens[lx], gens[ly], px, py), n, gens)
        r_yx = express(bracket(gens[ly], gens[lx], py, px), n, gens)
        sign = (-1) ** (px * py)
        all_keys = set(r_xy) | set(r_yx)
        for k in all_keys:
            v_xy = r_xy.get(k, Fraction(0))
            v_yx = r_yx.get(k, Fraction(0))
            assert v_xy == -sign * v_yx, (
                f"n={n}: antisymmetry [{lx},{ly}] fails on {k}: "
                f"{v_xy} != {-sign}*{v_yx}"
            )


# ── 5. Jacobi identity ────────────────────────────────────────────────────────

def _jacobi_triple(gens, par, n, lx, ly, lz):
    """Compute the Jacobi sum for (X, Y, Z); should be zero."""
    X, Y, Z = gens[lx], gens[ly], gens[lz]
    px, py, pz = par[lx], par[ly], par[lz]

    def br_expr(A, pA, B, pB):
        return express(bracket(A, B, pA, pB), n, gens)

    def gen_poly(coeffs):
        res: dict = {}
        for lbl, c in coeffs.items():
            for mono, v in gens[lbl].items():
                res[mono] = res.get(mono, Fraction(0)) + c * v
        return {k: v for k, v in res.items() if v}

    # [X, [Y, Z}]
    yz = bracket(Y, Z, py, pz)
    xyz = express(bracket(X, gen_poly(express(yz, n, gens)), px, par.get(next(iter(express(yz, n, gens)), "H_1"), 0)), n, gens)

    # This approach is complex; instead compute directly in poly form
    yz_poly = bracket(Y, Z, py, pz)
    xyz_poly = bracket(X, yz_poly, px, 0)  # parity of [Y,Z] = py^py (wrong)

    # Use correct parity: p([Y,Z]) = py + pz mod 2 for Lie superalgebras
    pyz = (py + pz) % 2
    xyz_poly = bracket(X, yz_poly, px, pyz)

    zx_poly  = bracket(Z, X, pz, px)
    pzx = (pz + px) % 2
    yzx_poly = bracket(Y, zx_poly, py, pzx)

    xy_poly  = bracket(X, Y, px, py)
    pxy = (px + py) % 2
    zxy_poly = bracket(Z, xy_poly, pz, pxy)

    sign1 = (-1) ** (px * pz)
    sign2 = (-1) ** (py * px)
    sign3 = (-1) ** (pz * py)

    total: dict = {}
    for poly, sign in [(xyz_poly, sign1), (yzx_poly, sign2), (zxy_poly, sign3)]:
        for k, v in poly.items():
            total[k] = total.get(k, Fraction(0)) + sign * v
    return {k: v for k, v in total.items() if v}


@pytest.mark.parametrize("n", [1, 2])
def test_jacobi_identity(n):
    """Jacobi identity: (-1)^{xz}[X,[Y,Z]] + (-1)^{yx}[Y,[Z,X]] + (-1)^{zy}[Z,[X,Y]] = 0."""
    gens, par, basis = build_generators(n)
    triples = [
        ("H_1", "E_eps1_del1_pp", "E_eps1_del1_mm"),
        ("H_1", "E_2del1_p", "E_2del1_m"),
        ("E_eps1_del1_pp", "E_eps1_del1_mp", "H_1"),
    ]
    for lx, ly, lz in triples:
        total = _jacobi_triple(gens, par, n, lx, ly, lz)
        result = express(total, n, gens) if total else {}
        assert not result, (
            f"n={n}: Jacobi [{lx},{ly},{lz}] = {result}, expected 0"
        )


# ── 6. JSON schema output ─────────────────────────────────────────────────────

@pytest.mark.parametrize("n", [1, 2, 3])
def test_schema_keys(n):
    """Schema 1 JSON has all required top-level keys in correct order."""
    schema = build_schema(n)
    required = [
        "schema_version", "algebra", "central_elements",
        "oscillator_generators", "oscillator_relations",
        "basis", "parity", "generator_realization",
        "structure_constants", "metadata",
    ]
    for key in required:
        assert key in schema, f"n={n}: missing key '{key}'"
    assert schema["schema_version"] == "5.0"
    assert schema["algebra"]["family"] == "C"
    assert schema["algebra"]["m"] == 1
    assert schema["algebra"]["n"] == n


@pytest.mark.parametrize("n", [1, 2, 3])
def test_schema_dimensions(n):
    schema = build_schema(n)
    dim = schema["algebra"]["dimension"]
    assert dim["even"] == dim_even(n)
    assert dim["odd"]  == dim_odd(n)
    assert dim["total"] == dim_total(n)


@pytest.mark.parametrize("n", [1, 2, 3])
def test_structure_constants_nonempty(n):
    schema = build_schema(n)
    assert len(schema["structure_constants"]) > 0


@pytest.mark.parametrize("n", [1, 2, 3])
def test_both_orderings_present(n):
    """Every (X,Y) entry with X≠Y must have a corresponding (Y,X) entry."""
    schema = build_schema(n)
    sc = schema["structure_constants"]
    # Build a set of all (X,Y) pairs that appear
    pairs = {(e["X"], e["Y"]) for e in sc}
    for x, y in list(pairs):
        if x != y:
            assert (y, x) in pairs, (
                f"n={n}: found ({x},{y}) in structure constants but not ({y},{x})"
            )


@pytest.mark.parametrize("n", [1, 2, 3])
def test_reverse_pair_sign(n):
    """[Y,X} = -(-1)^{px*py} [X,Y} — check one concrete pair."""
    schema = build_schema(n)
    gens, par, _ = build_generators(n)
    sc = schema["structure_constants"]

    def get_coeffs(x, y):
        return {e["Z"]: Fraction(e["coeff"]) for e in sc if e["X"] == x and e["Y"] == y}

    lx, ly = "H_1", "E_eps1_del1_pp"
    px, py = par[lx], par[ly]
    sign = (-1) ** (px * py)
    fwd = get_coeffs(lx, ly)
    rev = get_coeffs(ly, lx)
    for z in set(fwd) | set(rev):
        assert fwd.get(z, Fraction(0)) == -sign * rev.get(z, Fraction(0)), (
            f"n={n}: sign rule failed on Z={z}"
        )


@pytest.mark.parametrize("n", [1, 2, 3])
def test_parity_map_complete(n):
    """Every basis element appears in the parity map."""
    schema = build_schema(n)
    basis_all = schema["basis"]["odd"] + schema["basis"]["even"]
    for lbl in basis_all:
        assert lbl in schema["parity"], f"n={n}: {lbl} missing from parity map"


@pytest.mark.parametrize("n", [1, 2, 3])
def test_central_elements_present(n):
    schema = build_schema(n)
    ce = schema["central_elements"]
    assert "kappa" in ce and ce["kappa"]["parity"] == 1
    assert "K" in ce and ce["K"]["parity"] == 0

